            dicData["items"] = DataTableToList(dtbItems);

            WriteJson(context, true, "", dicData);
        }

        private void HandleData(HttpContext context)
        {
            string strTrainingLevelId = GetRequestValue(context, "trainingLevelId");
            string strCourseId = GetRequestValue(context, "courseId");
            string strSpecialBranchId = GetRequestValue(context, "specialBranchId");
            string strFromDate = GetRequestValue(context, "fromDate");
            string strToDate = GetRequestValue(context, "toDate");

            object objYearId = ResolveYearId();

            Dictionary<string, DataTable> dicTables = GetDashboardData(
                objYearId,
                strTrainingLevelId,
                strCourseId,
                strSpecialBranchId,
                strFromDate,
                strToDate);

            if (dicTables["summary"] == null)
            {
                WriteJson(context, false, "Không tải được dữ liệu từ hệ thống.", null);
                return;
            }

            Dictionary<string, object> dicData = new Dictionary<string, object>();
            dicData["summary"] = DataTableToList(dicTables["summary"]);
            dicData["bySpecialBranch"] = DataTableToList(dicTables["bySpecialBranch"]);
            dicData["byCourse"] = DataTableToList(dicTables["byCourse"]);
            dicData["byMonth"] = DataTableToList(dicTables["byMonth"]);
            dicData["updatedAt"] = DateTime.Now.ToString("dd/MM/yyyy HH:mm");
            dicData["debugFilter"] = BuildDebugFilter(
                objYearId,
                strTrainingLevelId,
                strCourseId,
                strSpecialBranchId,
                strFromDate,
                strToDate);

            WriteJson(context, true, "", dicData);
        }

        private Dictionary<string, object> BuildDebugFilter(
            object yearId,
            string trainingLevelId,
            string courseId,
            string specialBranchId,
            string fromDate,
            string toDate)
        {
            Dictionary<string, object> dic = new Dictionary<string, object>();
            dic["yearId"] = yearId == DBNull.Value || yearId == null ? null : yearId;
            dic["trainingLevelId"] = trainingLevelId;
            dic["courseId"] = courseId;
            dic["specialBranchId"] = specialBranchId;
            dic["fromDate"] = fromDate;
            dic["toDate"] = toDate;
            return dic;
        }

        private object ResolveYearId()
        {
            try
            {
                string strYear = SYS_SettingService.GetStringValue("CurrentYearID");
                if (strYear != null && strYear.Trim() != "" && strYear.Trim() != "0")
                    return Convert.ToInt32(strYear.Trim());
            }
            catch (Exception)
            {
            }
            return DBNull.Value;
        }

        private Dictionary<string, DataTable> GetDashboardData(
            object yearId,
            string trainingLevelId,
            string courseId,
            string specialBranchId,
            string fromDate,
            string toDate)
        {
            Dictionary<string, DataTable> dicResult = new Dictionary<string, DataTable>();
            SIM_StudentCollection objStudent = new SIM_StudentCollection();

            dicResult["summary"] = CallResultSet(objStudent, yearId, trainingLevelId, courseId, specialBranchId, fromDate, toDate, 1);
            dicResult["bySpecialBranch"] = CallResultSet(objStudent, yearId, trainingLevelId, courseId, specialBranchId, fromDate, toDate, 2);
            dicResult["byCourse"] = CallResultSet(objStudent, yearId, trainingLevelId, courseId, specialBranchId, fromDate, toDate, 3);
            dicResult["byMonth"] = CallResultSet(objStudent, yearId, trainingLevelId, courseId, specialBranchId, fromDate, toDate, 4);

            return dicResult;
        }

        private DataTable CallResultSet(
            SIM_StudentCollection objStudent,
            object yearId,
            string trainingLevelId,
            string courseId,
            string specialBranchId,
            string fromDate,
            string toDate,
            byte resultSet)
        {
            // Không truyền @YearID khi null — tránh lỗi convert DBNull của DAL
            if (yearId == null || yearId == DBNull.Value)
            {
                return objStudent.GetDataTable(
                    SP_DATA,
                    "@TrainingLevelID", NormalizeFilter(trainingLevelId),
                    "@CourseID", NormalizeFilter(courseId),
                    "@SpecialBranchID", NormalizeFilter(specialBranchId),
                    "@FromDate", NormalizeDate(fromDate),
                    "@ToDate", NormalizeDate(toDate),
                    "@ResultSet", resultSet);
            }

            return objStudent.GetDataTable(
                SP_DATA,
                "@YearID", yearId,
                "@TrainingLevelID", NormalizeFilter(trainingLevelId),
                "@CourseID", NormalizeFilter(courseId),
                "@SpecialBranchID", NormalizeFilter(specialBranchId),
                "@FromDate", NormalizeDate(fromDate),
                "@ToDate", NormalizeDate(toDate),
                "@ResultSet", resultSet);
        }

        private object NormalizeDate(string value)
        {
            if (String.IsNullOrEmpty(value) || value.Trim() == "")
                return DBNull.Value;

            string strValue = value.Trim();
            DateTime dtResult;

            if (DateTime.TryParseExact(
                strValue,
                "yyyy-MM-dd",
                CultureInfo.InvariantCulture,
                DateTimeStyles.None,
                out dtResult))
                return dtResult;

            if (DateTime.TryParse(
                strValue,
                CultureInfo.InvariantCulture,
                DateTimeStyles.None,
                out dtResult))
                return dtResult;

            if (DateTime.TryParse(strValue, out dtResult))
                return dtResult;

            return DBNull.Value;
        }

        private object NormalizeFilter(string value)
        {
            if (value == null || value.Trim() == "" || value == "0" || value.ToLower() == "all")
                return DBNull.Value;
            return value.Trim();
        }

        private List<Dictionary<string, object>> DataTableToList(DataTable dtb)
        {
            List<Dictionary<string, object>> lstRows = new List<Dictionary<string, object>>();
            if (dtb == null)
                return lstRows;

            int intCol;
            int intRow;
            for (intRow = 0; intRow < dtb.Rows.Count; intRow++)
            {
                Dictionary<string, object> dicRow = new Dictionary<string, object>();
                for (intCol = 0; intCol < dtb.Columns.Count; intCol++)
                {
                    object objValue = dtb.Rows[intRow][intCol];
                    // Giữ đúng tên cột từ SQL (PascalCase) để JS map ổn định
                    string strCol = dtb.Columns[intCol].ColumnName;
                    if (objValue == DBNull.Value)
                        dicRow[strCol] = null;
                    else if (objValue is DateTime)
                        dicRow[strCol] = ((DateTime)objValue).ToString("yyyy-MM-dd");
                    else
                        dicRow[strCol] = objValue;
                }
                lstRows.Add(dicRow);
            }
            return lstRows;
        }

        private string GetRequestValue(HttpContext context, string key)
        {
            Dictionary<string, object> dicBody = GetRequestBody(context);
            if (dicBody != null && dicBody.ContainsKey(key) && dicBody[key] != null)
                return Convert.ToString(dicBody[key]);

            if (context.Request[key] != null && context.Request[key] != "")
                return context.Request[key];

            return null;
        }

        private Dictionary<string, object> GetRequestBody(HttpContext context)
        {
            if (context.Items.Contains(BODY_CACHE_KEY))
                return context.Items[BODY_CACHE_KEY] as Dictionary<string, object>;

            string strBody = ReadRequestBody(context);
            Dictionary<string, object> dicBody = null;
            if (strBody != null && strBody.Trim() != "")
            {
                JavaScriptSerializer objSerializer = new JavaScriptSerializer();
                dicBody = objSerializer.Deserialize<Dictionary<string, object>>(strBody);
            }

            context.Items[BODY_CACHE_KEY] = dicBody;
            return dicBody;
        }

        private string ReadRequestBody(HttpContext context)
        {
            if (context.Request.InputStream == null)
                return null;

            if (context.Request.InputStream.CanSeek)
                context.Request.InputStream.Position = 0;

            StreamReader objReader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
            return objReader.ReadToEnd();
        }

        private string BuildErrorMessage(Exception ex)
        {
            if (ex == null)
                return "Có lỗi xảy ra khi tải dữ liệu dashboard.";

            string strMessage = ex.Message;
            if (ex.InnerException != null && ex.InnerException.Message != null && ex.InnerException.Message != "")
                strMessage = strMessage + " | " + ex.InnerException.Message;

            return strMessage;
        }

        private void WriteJson(HttpContext context, bool success, string message, object data)
        {
            Dictionary<string, object> dicResponse = new Dictionary<string, object>();
            dicResponse["success"] = success;
            dicResponse["message"] = message;
            dicResponse["data"] = data;

            JavaScriptSerializer objSerializer = new JavaScriptSerializer();
            objSerializer.MaxJsonLength = int.MaxValue;
            context.Response.Write(objSerializer.Serialize(dicResponse));
        }

        public bool IsReusable
        {
            get { return false; }
        }
    }
}

