using System;
using System.Data;
using System.Web.UI;
using System.Web.UI.WebControls;
using SimsObject;

namespace InformationWeb.Dashboards.Student
{
    public partial class StudentAdmissionDashboard : UserControl
    {
        /// <summary>
        /// Mặc định mở trang chỉ load Cao đẳng (CD) để giảm tải.
        /// </summary>
        public const string DefaultTrainingLevelID = "CD";

        public string TrainingLevelClientID
        {
            get { return "sadTrainingLevelFilter"; }
        }

        public string CourseClientID
        {
            get { return "sadCourseFilter"; }
        }

        public string SpecialBranchClientID
        {
            get { return "sadSpecialBranchFilter"; }
        }

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                LoadFilterLists();
            }
        }

        private void LoadFilterLists()
        {
            SIM_StudentCollection objStudent = new SIM_StudentCollection();

            DataTable dtbTrainingLevel = objStudent.GetDataTable(
                "DASH_StudentAdmission_GetFilter",
                "@CourseID", DBNull.Value,
                "@TrainingLevelID", DBNull.Value,
                "@ListType", (byte)3);
            rptTrainingLevel.DataSource = dtbTrainingLevel;
            rptTrainingLevel.DataBind();

            // Khóa / chuyên ngành chỉ theo bậc mặc định CD
            DataTable dtbCourse = objStudent.GetDataTable(
                "DASH_StudentAdmission_GetFilter",
                "@CourseID", DBNull.Value,
                "@TrainingLevelID", DefaultTrainingLevelID,
                "@ListType", (byte)1);
            rptCourse.DataSource = dtbCourse;
            rptCourse.DataBind();

            DataTable dtbBranch = objStudent.GetDataTable(
                "DASH_StudentAdmission_GetFilter",
                "@CourseID", DBNull.Value,
                "@TrainingLevelID", DefaultTrainingLevelID,
                "@ListType", (byte)2);
            rptSpecialBranch.DataSource = dtbBranch;
            rptSpecialBranch.DataBind();
        }
    }
}

