function applyDefaultTrainingLevel() {
    readFilterConfig();
    var defaultId = filterConfig.defaultTrainingLevelId || "CD";
    var container = getEl(filterConfig.trainingLevelId || "sadTrainingLevelFilter");
    if (!container) {
        return;
    }
    var checks = container.querySelectorAll(".scs-ms-check");
    var allCheck = container.querySelector(".scs-ms-check-all");
    var found = false;
    var i;
    for (i = 0; i < checks.length; i++) {
        if (checks[i].value === defaultId) {
            checks[i].checked = true;
            found = true;
        } else {
            checks[i].checked = false;
        }
    }
    if (allCheck) {
        allCheck.checked = false;
    }
    // Nếu không có CD trong list thì giữ "Tất cả" để vẫn xem được dữ liệu
    if (!found && allCheck) {
        allCheck.checked = true;
        for (i = 0; i < checks.length; i++) {
            checks[i].checked = true;
        }
    }
    updateMultiSelectAllState(container);
    updateMultiSelectCount(container);
}

function init() {
    if (!getEl("sadDashContent")) {
        return;
    }
    bindEvents();
    applyDefaultTrainingLevel();
    fetchDashboard();
}

